"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Plus, MoreHorizontal, Calendar, 
  Clock, CheckCircle, Loader2, X, DollarSign, 
  Flag, Trash2, User, Target
} from "lucide-react";

// DATA DUMMY
const initialProkers = [
  { 
    id: 1, title: "Class Meeting Semester Ganjil", sekbid: "Sekbid 3", status: "progress",
    startDate: "2026-01-15", endDate: "2026-01-20", progress: 65, priority: "High", 
    pic: "Dimas", picColor: "blue", budget: 2500000
  },
  { 
    id: 2, title: "Latihan Dasar Kepemimpinan (LDKS)", sekbid: "Inti", status: "todo",
    startDate: "2026-02-10", endDate: "2026-02-12", progress: 0, priority: "High",
    pic: "Raka", picColor: "purple", budget: 5000000
  },
  { 
    id: 3, title: "Pentas Seni: The Beginning", sekbid: "Sekbid 2", status: "todo",
    startDate: "2026-03-05", endDate: "2026-03-05", progress: 15, priority: "Medium",
    pic: "Siti", picColor: "pink", budget: 15000000
  },
  { 
    id: 4, title: "Perbaikan Mading Sekolah", sekbid: "Sekbid 1", status: "done",
    startDate: "2025-12-01", endDate: "2025-12-05", progress: 100, priority: "Low",
    pic: "Budi", picColor: "green", budget: 500000
  },
];

export default function ProkerPage() {
  const [prokers, setProkers] = useState(initialProkers);
  const [filterSekbid, setFilterSekbid] = useState("Semua");
  const [searchQuery, setSearchQuery] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  
  // STATE FORM BARU
  const [newProker, setNewProker] = useState({
    title: "", sekbid: "Inti", priority: "Medium", 
    startDate: "", endDate: "", pic: "", budget: ""
  });
  const [progressInput, setProgressInput] = useState(0);

  // --- ACTIONS ---

  // 1. Tambah Proker
  const handleAddProker = () => {
    if (!newProker.title) return alert("Nama kegiatan wajib diisi!");
    
    const item = {
      id: Date.now(),
      ...newProker,
      budget: Number(newProker.budget),
      progress: progressInput,
      status: progressInput === 100 ? 'done' : progressInput > 0 ? 'progress' : 'todo',
      picColor: ["blue", "purple", "pink", "orange", "green"][Math.floor(Math.random() * 5)] // Random color
    };

    setProkers([item, ...prokers] as any);
    setIsModalOpen(false);
    // Reset Form
    setNewProker({ title: "", sekbid: "Inti", priority: "Medium", startDate: "", endDate: "", pic: "", budget: "" });
    setProgressInput(0);
  };

  // 2. Hapus Proker
  const handleDelete = (id: number) => {
    if(confirm("Hapus program kerja ini?")) {
      setProkers(prokers.filter(p => p.id !== id));
    }
  };

  // --- FILTERS ---
  const filteredProkers = prokers.filter((item) => {
    const matchSekbid = filterSekbid === "Semua" ? true : item.sekbid === filterSekbid;
    const matchSearch = item.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchSekbid && matchSearch;
  });

  const todos = filteredProkers.filter(p => p.status === 'todo');
  const inProgress = filteredProkers.filter(p => p.status === 'progress');
  const done = filteredProkers.filter(p => p.status === 'done');

  return (
    <div className="relative h-full flex flex-col min-h-screen font-sans">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-8">
        <div>
           <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
             Program Kerja <span className="text-2xl p-2 bg-pink-100 dark:bg-pink-900/30 rounded-full">📅</span>
           </h1>
           <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1">Monitoring progres kegiatan dalam tampilan Kanban.</p>
        </div>
        
        <button onClick={() => setIsModalOpen(true)} className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold shadow-lg shadow-blue-600/30 flex items-center gap-2 transition-transform active:scale-95">
           <Plus size={20} /> Buat Proker Baru
        </button>
      </div>

      {/* TOOLBAR */}
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-8 bg-white/50 dark:bg-white/5 p-2 rounded-2xl border border-slate-200 dark:border-white/5 backdrop-blur-sm">
         <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0 scrollbar-hide">
            {['Semua', 'Inti', 'Sekbid 1', 'Sekbid 2', 'Sekbid 3'].map((sekbid) => (
               <button key={sekbid} onClick={() => setFilterSekbid(sekbid)} className={`px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap transition-all border ${filterSekbid === sekbid ? "bg-white dark:bg-slate-700 text-blue-600 dark:text-white border-blue-100 dark:border-transparent shadow-sm" : "bg-transparent border-transparent text-slate-500 hover:bg-white/50 dark:hover:bg-white/5"}`}>
                  {sekbid}
               </button>
            ))}
         </div>
         <div className="relative flex-1 md:w-72 group w-full">
            <input type="text" placeholder="Cari program kerja..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 focus:ring-2 focus:ring-blue-500/50 outline-none text-sm font-medium text-slate-700 dark:text-white shadow-sm"/>
            <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
         </div>
      </div>

      {/* KANBAN BOARD */}
      <div className="flex-1 overflow-x-auto pb-8 custom-scrollbar">
         <div className="flex flex-col md:flex-row gap-6 min-w-[1000px] md:min-w-0">
            <KanbanColumn title="Rencana (To Do)" icon={<Calendar size={18} />} count={todos.length} color="slate">
               {todos.map((item) => <ProkerCard key={item.id} data={item} onDelete={handleDelete} />)}
            </KanbanColumn>
            <KanbanColumn title="Sedang Berjalan" icon={<Loader2 size={18} className="animate-spin" />} count={inProgress.length} color="blue">
               {inProgress.map((item) => <ProkerCard key={item.id} data={item} onDelete={handleDelete} />)}
            </KanbanColumn>
            <KanbanColumn title="Selesai (Done)" icon={<CheckCircle size={18} />} count={done.length} color="green">
               {done.map((item) => <ProkerCard key={item.id} data={item} onDelete={handleDelete} />)}
            </KanbanColumn>
         </div>
      </div>

      {/* MODAL INPUT */}
      <AnimatePresence>
         {isModalOpen && (
            <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
               <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsModalOpen(false)} className="absolute inset-0 bg-black/60 backdrop-blur-sm"/>
               <motion.div initial={{ scale: 0.95, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.95, opacity: 0, y: 20 }} className="relative w-full max-w-2xl bg-white dark:bg-[#0f172a] rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200 dark:border-white/10 flex flex-col max-h-[90vh]">
                  
                  <div className="p-6 border-b border-slate-100 dark:border-white/5 flex justify-between items-center">
                     <div><h2 className="text-xl font-black text-slate-900 dark:text-white">Proker Baru</h2><p className="text-xs text-slate-500 mt-1">Rencanakan kegiatan dengan detail.</p></div>
                     <button onClick={() => setIsModalOpen(false)}><X size={24} className="text-slate-400" /></button>
                  </div>

                  <div className="p-8 overflow-y-auto flex-1 space-y-6 custom-scrollbar">
                     <div className="space-y-4">
                        <div>
                           <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Nama Kegiatan</label>
                           <input type="text" value={newProker.title} onChange={e => setNewProker({...newProker, title: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" placeholder="Contoh: LDKS 2026" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                           <div>
                              <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Sekbid</label>
                              <select value={newProker.sekbid} onChange={e => setNewProker({...newProker, sekbid: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white">
                                 <option>Inti</option><option>Sekbid 1</option><option>Sekbid 2</option><option>Sekbid 3</option>
                              </select>
                           </div>
                           <div>
                              <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Prioritas</label>
                              <select value={newProker.priority} onChange={e => setNewProker({...newProker, priority: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white">
                                 <option>High</option><option>Medium</option><option>Low</option>
                              </select>
                           </div>
                        </div>
                     </div>

                     <div className="border-t border-slate-100 dark:border-white/5 my-4"></div>

                     <div className="grid grid-cols-2 gap-4">
                        <div><label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Mulai</label><input type="date" value={newProker.startDate} onChange={e => setNewProker({...newProker, startDate: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" /></div>
                        <div><label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Selesai</label><input type="date" value={newProker.endDate} onChange={e => setNewProker({...newProker, endDate: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" /></div>
                        <div><label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Ketua (PIC)</label><input type="text" placeholder="Nama..." value={newProker.pic} onChange={e => setNewProker({...newProker, pic: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" /></div>
                        <div><label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Anggaran (Rp)</label><input type="number" placeholder="0" value={newProker.budget} onChange={e => setNewProker({...newProker, budget: e.target.value})} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 outline-none focus:border-blue-500 text-sm font-bold dark:text-white" /></div>
                     </div>

                     <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-xl border border-blue-100 dark:border-blue-500/20">
                        <div className="flex justify-between items-center mb-2"><label className="text-xs font-bold text-blue-700 dark:text-blue-300 uppercase block">Progress Awal</label><span className="text-sm font-black text-blue-600 dark:text-white">{progressInput}%</span></div>
                        <input type="range" min="0" max="100" value={progressInput} onChange={(e) => setProgressInput(parseInt(e.target.value))} className="w-full h-2 bg-blue-200 rounded-lg appearance-none cursor-pointer accent-blue-600" />
                     </div>
                  </div>

                  <div className="p-6 border-t border-slate-100 dark:border-white/5 bg-slate-50 dark:bg-white/5 flex justify-end gap-3">
                     <button onClick={() => setIsModalOpen(false)} className="px-6 py-3 rounded-xl text-sm font-bold text-slate-500 hover:bg-slate-200 dark:hover:bg-white/10 transition-colors">Batal</button>
                     <button onClick={handleAddProker} className="px-8 py-3 rounded-xl bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold shadow-lg shadow-blue-500/30">Simpan Proker</button>
                  </div>
               </motion.div>
            </div>
         )}
      </AnimatePresence>
    </div>
  );
}

// === KOMPONEN KOLOM KANBAN ===
function KanbanColumn({ title, icon, count, children, color }: any) {
   const colors: any = {
      slate: "bg-slate-100/50 dark:bg-slate-900/30 border-slate-200/50 dark:border-white/5",
      blue: "bg-blue-50/50 dark:bg-blue-900/10 border-blue-100 dark:border-blue-500/10",
      green: "bg-green-50/50 dark:bg-green-900/10 border-green-100 dark:border-green-500/10",
   }
   return (
      <div className={`flex-1 rounded-[2rem] p-4 border ${colors[color]} flex flex-col min-h-[500px]`}>
         <div className="flex items-center justify-between mb-4 px-2">
            <div className="flex items-center gap-2 font-bold text-slate-600 dark:text-slate-300">{icon} <span className="text-sm">{title}</span></div>
            <span className="px-2.5 py-0.5 rounded-full bg-white dark:bg-white/10 text-xs font-bold text-slate-500 dark:text-slate-400 shadow-sm">{count}</span>
         </div>
         <div className="space-y-3 flex-1">{children}</div>
      </div>
   )
}

// === KOMPONEN KARTU PROKER (FIXED COLORS) ===
function ProkerCard({ data, onDelete }: any) {
   // FIXED: Color Mapping (Bukan string interpolation)
   const colorVariants: any = {
      blue: "from-blue-400 to-blue-600",
      purple: "from-purple-400 to-purple-600",
      pink: "from-pink-400 to-pink-600",
      green: "from-green-400 to-green-600",
      orange: "from-orange-400 to-orange-600",
   };

   return (
      <motion.div layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} whileHover={{ y: -4, boxShadow: "0 10px 30px -10px rgba(0,0,0,0.1)" }} className="bg-white dark:bg-[#1e293b] p-4 rounded-2xl border border-slate-100 dark:border-white/5 shadow-sm cursor-grab active:cursor-grabbing group relative overflow-hidden">
         <div className="flex justify-between items-start mb-3">
            <span className="px-2 py-1 rounded-lg bg-slate-50 dark:bg-white/5 text-[10px] font-bold text-slate-500 dark:text-slate-400 border border-slate-100 dark:border-white/5 uppercase tracking-wide">{data.sekbid}</span>
            <button onClick={() => onDelete(data.id)} className="text-slate-300 hover:text-red-500 transition-colors" title="Hapus"><Trash2 size={16} /></button>
         </div>

         <h3 className="font-bold text-slate-800 dark:text-slate-100 text-sm mb-3 leading-snug group-hover:text-blue-600 transition-colors">{data.title}</h3>

         <div className="mb-4">
            <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1"><span>Progress</span><span>{data.progress}%</span></div>
            <div className="w-full h-1.5 bg-slate-100 dark:bg-white/5 rounded-full overflow-hidden">
               <div className={`h-full rounded-full transition-all duration-500 ${data.progress === 100 ? 'bg-green-500' : 'bg-blue-500'}`} style={{ width: `${data.progress}%` }} />
            </div>
         </div>

         <div className="flex items-center justify-between pt-3 border-t border-slate-50 dark:border-white/5">
            <div className="flex items-center gap-2">
               <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[8px] font-bold text-white bg-gradient-to-br ${colorVariants[data.picColor] || colorVariants.blue}`}>
                  {data.pic.charAt(0)}
               </div>
               <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300">{data.endDate}</span>
                  {data.budget > 0 && <span className="text-[9px] text-slate-400 font-mono">{new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(data.budget)}</span>}
               </div>
            </div>
            {data.priority === 'High' && <div className="flex items-center gap-1 text-[10px] font-bold text-red-500 bg-red-50 dark:bg-red-500/10 px-2 py-0.5 rounded-full"><Flag size={10} fill="currentColor" /> High</div>}
         </div>
      </motion.div>
   )
}